+/** Sends a failed send again (ADR 0006). The update reads its state with `PollFailedEmailCmd`. */
+export const ResendFailedEmailCmd = Command.define("ResendFailedEmailCmd", {
+  args: { sendId: SendId },
+  messages: [Message.ResentFailedEmail],
+  execute: ({ sendId }) =>
+    runApi(
